package dev.maw.client.mixin;

import dev.maw.client.ClientBridge;
import net.minecraft.client.gui.components.ChatComponent;
import net.minecraft.network.chat.Component;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

/** Filter only the local status generated by our finite Minescript runner. */
@Mixin(value=ChatComponent.class,priority=1100)
public abstract class ChatComponentMixin {
    @Inject(method="<init>",at=@At("RETURN"))
    private void maw$ready(CallbackInfo callback){ClientBridge.chatFilterReady();}
    @Inject(method="addMessage(Lnet/minecraft/network/chat/Component;)V",at=@At("HEAD"),cancellable=true)
    private void maw$privateStatus(Component message,CallbackInfo callback){
        if(ClientBridge.hideOwnedMinescriptStatus(message))callback.cancel();
    }
}
